mapper.update:
update insp_task
executor_id = #{executorId}, plan_date = #{planDate}, actual_time = #{actualTime}, result = #{result}, abnormal_desc = #{abnormalDesc}, order_id = #{orderId}, status = #{status}, update_time = #{updateTime},
where id = #{id}

mapper.select:
select t.id, t.task_no, t.plan_id, p.name as plan_name, t.device_id, d.name as device_name,
       t.executor_id, s.name as executor_name, t.plan_date, t.actual_time,
       t.result, t.abnormal_desc, t.order_id, t.status
from insp_task t
left join insp_plan p on p.id = t.plan_id
left join dev_device d on d.id = t.device_id
left join sys_staff s on s.id = t.executor_id

    and t.plan_id = #{planId}
    and t.executor_id = #{executorId}
    and t.status = #{status}
    and t.result = #{result}
    and t.plan_date >= #{beginDate}
    and t.plan_date <= #{endDate}

order by t.plan_date desc, t.id desc
